The model is not a black box here.  The reference stores the token ids of three
fixed prompts and the logprob of every forced token.  A check scores the same"    LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


def main() -> None:
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "save":
        name = sys.argv[2]
        path = D / f"{name}.json"
        path.write_text(json.dumps(collect(), indent=2) + "\n")
        print(f"  saved {path}")
    elif cmd == "check":
        ref_name = sys.argv[2]
        current = collect(cached=json.loads((D / f"{ref_name}.json").read_text()))
        report = stats(json.loads((D / f"{ref_name}.json").read_text()), current)
        print_report(f"current vs {ref_name}", report)
    elif cmd == "compare":
        a_name, b_name = sys.argv[2], sys.argv[3]
        a = json.loads((D / f"{a_name}.json").read_text())
        b = json.loads((D / f"{b_name}.json").read_text())
        print_report(f"{b_name} vs {a_name}", stats(a, b))
    else:
        print(__doc__)
        sys.exit(1)


if __name__ == "__main__":
    main()


